export const getListStashTasksUrl = (
  spaceId: string,
  params?: ListStashTasksParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `${process.env.WBD_API_BASE_URL ?? ""}/api/v1/spaces/${spaceId}/stash/tasks?${stringifiedParams}`
    : `${process.env.WBD_API_BASE_URL ?? ""}/api/v1/spaces/${spaceId}/stash/tasks`;
};

